  screen_color(rgb(11, 15, 25));

  // Carga explícita de recursos gráficos, fuentes y sonidos (DIV Games Studio)
  fpg_pong = load_fpg("cyber_pong.fpg");
  fnt_cyber = load_fnt("digital.fnt");
